{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_5",
      "quote": "This systematic review aims to address the following PIO question: 'What is the effect of social media on prevention and promotion of oral health compared with conventional strategies among lay people of any age without disability or systematic diseases?'. The review encompasses (P) laypeople from diverse backgrounds, including different age groups, genders, socioeconomic statuses, ethnicities without any disability or systematic diseases. The focus is on (I) social media-based interventions that employ a group approach for information dissemination. The desired outcomes include (O) any changes in oral health status, knowledge, beliefs, and attitudes resulting from social media interventions. This includes short and long-term effects, regardless of the duration of follow-up. The full-text articles from 2012 to 2023 focus on randomized controlled trials (RCTs), quasi-randomized trials and field trials were included in the current study.",
      "reason": "The eligibility criteria specify the PIO framework components, eligible study designs (RCTs, quasi-randomized trials, field trials), settings (laypeople without disability or systematic diseases), and follow-up requirements (short and long-term effects)."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_5",
      "quote": "The full-text articles from 2012 to 2023 focus on randomized controlled trials (RCTs), quasi-randomized trials and field trials were included in the current study. Studies that did not specifically target oral disease prevention or oral health promotion, were not based on social media approaches, had an intervention on oral health promotion of people with systematic disease or disability or were published in languages other than English were excluded. The conference proceedings, editorials, commentaries, review articles, pilot studies and all the studies that assessed the quality of the content of social media were excluded.",
      "reason": "Eligibility criteria specify dissemination year (2012-2023), language (English only), and publication status (exclusion of conference proceedings, editorials, etc.)."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence found distinguishing exclusion due to outcomes not measured from exclusion due to outcome results not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PARTIAL",
      "chunk_id": "text_10",
      "quote": "Eight studies employed a design in which two or more groups were compared [14-21], and the rest reported changes before and after the intervention within a single study group [22, 23].",
      "reason": "Groups in studies are specified, but not explicitly linked to the synthesis or comparisons defined in review objectives."
    },
    {
